def parse_env_lines(text):
    result = {}
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError("invalid env line")
        key, value = line.split('=', 1)
        result[key.strip()] = value.strip()
    return result

