import json
import sys

def main():
    for raw in sys.stdin:
        if not raw.strip():
            continue
        try:
            item = json.loads(raw)
            if not isinstance(item, dict) or not isinstance(item.get('name'), str) or not isinstance(item.get('value'), (int, float)):
                raise ValueError('invalid record')
            print(json.dumps({'name': item['name'], 'value': item['value'] * 2}, sort_keys=True))
        except (json.JSONDecodeError, ValueError, TypeError) as exc:
            print(str(exc), file=sys.stderr)
            return 2
    return 0

if __name__ == '__main__':
    raise SystemExit(main())

