import os
from dataclasses import dataclass

@dataclass
class Settings:
    timeout_seconds: int = 5
    @classmethod
    def from_sources(cls, cli_timeout=None):
        raw = cli_timeout if cli_timeout is not None else os.getenv('APP_TIMEOUT', 5)
        value = int(raw)
        if value <= 0:
            raise ValueError('timeout must be positive')
        return cls(value)

