import csv
from io import StringIO

def read_records(text):
    rows = csv.DictReader(StringIO(text.strip()))
    if not rows.fieldnames or not {'name', 'score'}.issubset(set(rows.fieldnames)):
        raise ValueError('missing required columns')
    result = []
    for row in rows:
        if not any(str(value or '').strip() for value in row.values()):
            continue
        try:
            result.append({'name': str(row['name']).strip(), 'score': float(row['score'])})
        except (TypeError, ValueError) as exc:
            raise ValueError('invalid score') from exc
    return result

